function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

const user = { id: 1, name: "Ana" };
const name = getProperty(user, "name"); // string
getProperty(user, "email");            // erro: não é chave de user

interface Entity { id: number }

interface Repository<T extends Entity> {
  findById(id: number): Promise<T | null>;
  findAll(): Promise<T[]>;
  create(data: Omit<T, "id">): Promise<T>;
}

interface Product extends Entity { name: string; price: number }
declare const products: Repository<Product>;
products.create({ name: "Caneca", price: 30 });

